import { createWriteStream, readFileSync } from "fs"
import { promisify } from "util";

import { sportNameMap } from "../sportNameMap.js";
import { marketNameMap } from "../marketNameMap.js";
import { replaceNumericTeamName, stripTeamName } from "../util/stripTeamName.js";
import { insertCoefIntoOdd, insertMarketIntoMatch, insertMatchIntoSport, insertOddIntoMarket, insertSportIntoData } from "../../data/util/inserter.js";

// generated by chatGPT https://chatgpt.com/c/a9300588-42f8-40ee-bff4-b00c945cee1e
function convDatetimeToISO(dateStr){

  const parseDateStr = (dateStr) => {
    const [datePart, timePart] = dateStr.split(' ');
    const [day, month] = datePart.split('.');
    const [hours, minutes] = timePart.split(':');
  
    const currentYear = new Date().getFullYear();
    
    // Create a new Date object with the parsed values
    const date = new Date(currentYear, parseInt(month) - 1, parseInt(day), parseInt(hours), parseInt(minutes), 0, 0);
  
    return date;
  }; 
  
  const date = parseDateStr(dateStr);

  // Format the date as ISO 8601
  return date.toISOString();
}

export async function scrapeMatchURL(data, browser, book, i){
  
  const page = await browser.newPage();
  await page.setViewport(book.viewport);
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36');
  await page.setExtraHTTPHeaders({ 'Accept-Language': 'en-US,en;q=0.9' });
  await page.goto(book.urls[i], {waitUntil:'domcontentloaded'});
  const bookAbbrev = book.abbrev; 
  // open a file for logging
  const logFilePath = `books/${bookAbbrev}/log.txt`
  const log = createWriteStream(logFilePath, {flags: 'a'});
  // load the book-specific mappings from json files
  const sportNameMappingPath = `books/${bookAbbrev}/sportNameMapping.json`;
  let sportNameMapping;
  try{
    sportNameMapping = Object.freeze(JSON.parse(readFileSync(sportNameMappingPath)));
    if(!sportNameMapping){ throw error(); }
  } catch (error){
    log.write(`Failure! Cannot open file ${sportNameMappingPath} or incorrect JSON format\n`);
    return -10;
  }
  const marketNameMappingPath = `books/${bookAbbrev}/marketNameMapping.json`;
  let marketNameMapping;
  try{
    marketNameMapping = Object.freeze(JSON.parse(readFileSync(marketNameMappingPath)));
    if(!marketNameMapping){ throw error(); }
  } catch (error){
    log.write(`Failure! Cannot open file ${marketNameMappingPath} or incorrect JSON format\n`);
    return -10;
  }

  try{
//console.log('data: ');
//console.log(JSON.stringify(data, null, 2));
    let selector, el, mapping;
    // get sport
    selector = 'ul.liga_menu > li.open > a.link';
    el = await page.waitForSelector(selector);
    const sportTournament = await page.evaluate(e => e.textContent.trim().split('\u000a')[0].split('. '), el);
    let sportName = sportTournament[0].trim();
    mapping = sportNameMapping.find( m => m.specificName === sportName);
    if(mapping){
      sportName = sportNameMap[mapping.globalID];
    } else{
      log.write(`Failure! sportName Mapping of '${sportName}' does not exist in ${sportNameMappingPath}\n`);
      return 20;
    }
    let sport =  insertSportIntoData(log, data, sportName);

    // get tournament
//     let tournamentName = sportTournament[1].trim();
//     mapping = tournamentNameMapping.find( m => m.specificName === tournamentName);
//     if(mapping){
//       tournamentName = tournamentNameMap[mapping.globalID];;
//     } else{
//       log.write(`Failure! tournamentName Mapping of '${tournamentName}' does not exist in ${tournamentNameMappingPath}\n`);
//       return;
//     }
//     let tournament = sport.tournaments.findLast(t => t.name === tournamentName );
//     if(!tournament){
//       /* tournament is new */
//       sport.tournaments.push({ name: tournamentName, matches: [] });
//       tournament = sport.tournaments.findLast(t => t.name === tournamentName);
//     }

    // get teamHome, teamAway
    selector = 'a.link.open > span';
    const teamsDatetime = await page.$$eval(selector, es => es.map( e => e.textContent) );
    const teamHome = stripTeamName(teamsDatetime[0].split(' - ')[0]);
    const teamAway = stripTeamName(teamsDatetime[0].split(' - ')[1]);
    
    // get datetime, mode
    const datetime = convDatetimeToISO( teamsDatetime[1].trim() );
    let match = insertMatchIntoSport(log, sport, teamHome, teamAway, datetime, book.name, book.urls[i]);

    // GET ALL THE MARKETS > ODDS > COEFS FOR THIS MATCH
    selector = '#game-filters';
    const options = await page.$$eval(`${selector} > option`, options => options.map( o => o.value));
    const optionNames = await page.$$eval(`${selector} > option`, options => options.map( o => o.textContent.replace('\u000a', '\u0020').trim()));
    for(let i = 0; i < options.length; i++){
      selector = '#game-filters';
      await page.select(selector, options[i]);
      selector = 'div.bet_group';
      let marketHandles = await page.$$(selector);
      for(const marketHandle of marketHandles){
        // get marketName
        selector = 'div.bet-title';
        let marketName = await marketHandle.$eval(selector, e => e.textContent.trim());
        const ogirinalMarketName = marketName; // is used later to remove it from the oddName where it is duplicated
        marketName = i === 0 ? marketName : `${optionNames[i]} ${marketName}`;
        mapping = marketNameMapping.find( m => m.specificName === marketName);
        if(mapping){
          marketName = marketNameMap[mapping.globalID];
        } else{
          log.write(`Warning! marketName Mapping of '${marketName}' does not exist in ${marketNameMappingPath}\n`);
          continue;
        }
        let market = insertMarketIntoMatch(log, match, marketName);
        // get odds
        selector = 'div.market-row__inner';
        const oddHandles = await marketHandle.$$(selector);
        for(const oddHandle of oddHandles){
          selector = 'span';
          const nameValue = await oddHandle.$$eval(selector, es => es.map(e => e.textContent));
          let oddName = stripTeamName(nameValue[0]);
          // remove the marketName repeated in the oddName care that the oddName has already been stripTM'd
          for(const word of ogirinalMarketName.toLowerCase().split(' ').map(w => w.replace(/[^a-zA-Z0-9]/g, ''))){
            if(word === 'beat'){
              oddName = oddName.replace('1', '');
              oddName = oddName.replace('be', '');
              oddName = oddName.replace('beaten', '');
              oddName = oddName.replace('by', '');
            }
            oddName = oddName.replace(word, '');
          }
          // additional special case removals
          if(market.name.includes('First Blood')){
            oddName = oddName.replace('-', '');
          }else if(market.name.includes('Total')){
            oddName = oddName.replace(/tu|to/, (m) => m == 'tu' ? 'under' : 'over');
          } else if(market.name.includes('Handicap')){
            oddName = oddName.replace(/[()+]/g, '').replace(/maps|frags|rounds/g, '').replace('handiсap', '');
          } else if(market.name.includes('Correct Score')){
            oddName = oddName.replace('-yes', '').replace('-', ':');
            if (market.teamHome === teamAway && market.teamAway === teamHome){ // in case of CS market and flipped teamNames, the oddNames in the form of '2:0', etc. need to be flipped as well
              const [left, right] = oddName.split(':');
              oddName = `${right}:${left}`;
            }
          } else if(market.name.includes('First Tower')){
            oddName = replaceNumericTeamName(oddName, teamHome, teamAway);
            oddName = oddName.replace('to1', '');
          } else if(market.name.includes('First to Reach')){
            const [count, team] = oddName.split('-w');
            oddName = `${team}${count}`;
          } else if(market.name.includes('First Inhibitor')){
            oddName = oddName.replace('inhibirtobeed-w', '');
          } else if(market.name.includes('Yes/No')){
            oddName = oddName.replace('-', '');
          } else if(market.name.includes('Even/Odd')){
            oddName = oddName.replace(/-yes|-no/, m => m === '-yes' ? 'even' : 'odd');
          } else if(market.name.includes('Overtime')){
            oddName = oddName.replace('re?-', '');
          } else if(market.name.includes('First Dragon')){ // special case, because 22bet has odds for 2nd dragon in here as well
            if(oddName.match(/\d/)){
              continue;
            }
          }
          oddName = oddName.replace(/\s+/g, '');
          let odd = insertOddIntoMarket(log, market, oddName);
          const value = parseFloat(nameValue[1]);
          let coef = insertCoefIntoOdd(log, odd, book.name, value);
        }
      }
    }

  log.write(`Success! scraping a match from ${book.urls[i]}\n`);
  return 0;

  } catch (error){
    log.write(`Critical Failure! scraping a match from ${book.urls[i]}\n`);
    return -1;
  } finally{
    try{
      await page?.close()
    } catch{}
    await promisify(log.end).bind(log);
  }
}